     4944:       png_error(png_ptr, "inflateReset failed");
     4945:    png_ptr->zstream.avail_in = 0;
     4946:    png_ptr->zstream.next_in = 0;
     4947:    png_ptr->zstream.next_out = png_ptr->row_buf;
     4948:    png_ptr->zstream.avail_out =
>>>  4949:       (uInt)PNG_ROWBYTES(png_ptr->pixel_depth, png_ptr->iwidth) + 1;
     4950: }
